-- Audited canonical skills; existing order preserved; unchanged rows skipped.
begin;
on conflict (id) do update set name=excluded.name, type=excluded.type, source_type=excluded.source_type, mp_cost=excluded.mp_cost, damage_formula=excluded.damage_formula, effect=excluded.effect, skill_description=excluded.skill_description, skill_shape=excluded.skill_shape, "range"=excluded."range", aoe_radius=excluded.aoe_radius, projectile_speed=excluded.projectile_speed, cooldown_seconds=excluded.cooldown_seconds, arc_angle_degrees=excluded.arc_angle_degrees, target_attack=excluded.target_attack, target_effect=excluded.target_effect, stat_modifiers=excluded.stat_modifiers, periodic_effects=excluded.periodic_effects, control_effects=excluded.control_effects, special_effects=excluded.special_effects, usage_requirements=excluded.usage_requirements
where row(skills.name, skills.type, skills.source_type, skills.mp_cost, skills.damage_formula, skills.effect, skills.skill_description, skills.skill_shape, skills."range", skills.aoe_radius, skills.projectile_speed, skills.cooldown_seconds, skills.arc_angle_degrees, skills.target_attack, skills.target_effect, skills.stat_modifiers, skills.periodic_effects, skills.control_effects, skills.special_effects, skills.usage_requirements) is distinct from row(excluded.name, excluded.type, excluded.source_type, excluded.mp_cost, excluded.damage_formula, excluded.effect, excluded.skill_description, excluded.skill_shape, excluded."range", excluded.aoe_radius, excluded.projectile_speed, excluded.cooldown_seconds, excluded.arc_angle_degrees, excluded.target_attack, excluded.target_effect, excluded.stat_modifiers, excluded.periodic_effects, excluded.control_effects, excluded.special_effects, excluded.usage_requirements);
commit;
